# Test the orthogonalization hypothesis: does any writer matrix annihilate a candidate readout direction?
import torch, numpy as np
E = load_original('model.language_model.embed_tokens.weight').float()
G = load_original('model.language_model.norm.weight').float()
def readout(tid):
    r = E[tid]*(1+G)
    return r/ r.norm()
cands = {'im_end':248046, 'endoftext':248044, 'think_close':248069, 'think_open':248068}
dcands = {k: readout(v) for k,v in cands.items()}
writers = [n for n in names if ('down_proj.weight' in n or 'o_proj.weight' in n or 'out_proj.weight' in n) and 'visual' not in n and 'mtp' not in n]
print('writers', len(writers))
for k, d in dcands.items():
    print('='*40, k)
    worst = []
    for n in writers:
        W = load_original(n).float()
        val = (d @ W).norm().item()   # ~|d||W| if untouched ~ small if orthogonalized
        # normalize by |d||W|
        rel = val / (W.norm().item() + 1e-9)
        worst.append((rel, n))
    worst.sort(key=lambda x: x[0])
    for rel, n in worst[:6]:
        print(f'  rel={rel:.2e}  {n}')

# Broad scan: for each 2D writer/compute matrix, compare top singular values to siblings
import torch, numpy as np, time
groups = {}
for n in names:
    W = load_original(n)
    if W.dim() != 2 or 'visual' in n or 'mtp' in n: continue
    key = (W.shape[0], W.shape[1])
    groups.setdefault(key, []).append(n)
for key, ns in groups.items():
    if len(ns) < 2: continue
    vals = []
    for n in ns:
        sv = torch.linalg.svdvals(load_original(n).float())
        vals.append((sv[0].item(), sv[1].item() if len(sv)>1 else 0.0, n))
    arr = np.array([v[0] for v in vals])
    md, sd = arr.mean(), arr.std()+1e-9
    for v0, v1, n in vals:
        if abs(v0-md) > 2.5*sd:
            print(f'OUTLIER sv0={v0:.3f} (group mean {md:.3f} sd {sd:.3f}) {n}')

