import torch, shutil, os
d = torch.from_numpy(np.load('/work/loop_dir22.npy')).float()
d = d / d.norm()
edits = {}
for L in [18,19,20,21,22,23]:
    writers = [f'model.language_model.layers.{L}.mlp.down_proj.weight']
    la = f'model.language_model.layers.{L}.linear_attn.out_proj.weight'
